// ─── File: LockDowngradeDemo.java ───
// Runnable demo. In a real project each class lives in its own file.
package com.bank.rate;

import java.math.BigDecimal;
import java.util.concurrent.*;
import java.util.logging.*;

public class LockDowngradeDemo {
    private static final Logger LOG = Logger.getLogger("Rate");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        LOG.setUseParentHandlers(false);
        LOG.addHandler(h);
        LOG.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        RateStore store = new RateStore(new BigDecimal("6.50"), LOG);
        ExecutorService pool = Executors.newFixedThreadPool(5);

        for (int i = 0; i < 4; i++)                       // many concurrent readers
            pool.submit(() -> LOG.info(() -> "read rate = " + store.readRate()));

        // one writer downgrades to read the fresh factor safely
        pool.submit(() -> {
            BigDecimal factor = store.updateAndComputeFactor(new BigDecimal("7.25"));
            LOG.info(() -> "writer computed daily factor = " + factor);
        });

        pool.shutdown();
        pool.awaitTermination(2, TimeUnit.SECONDS);
        store.demonstrateCorrectUpgradeWorkaround();      // release→acquire→recheck
    }
}

// ─── Would be in store/RateStore.java ───
class RateStore {
    private final java.util.concurrent.locks.ReentrantReadWriteLock rw =
        new java.util.concurrent.locks.ReentrantReadWriteLock();
    private BigDecimal rate;
    private final Logger log;
        RateStore(BigDecimal rate, Logger log) { this.rate = rate;
        this.log = log; }

    // Safe concurrent read — many threads at once.
    BigDecimal readRate() {
        rw.readLock().lock();
        try { return rate; } finally { rw.readLock().unlock(); }
    }

    // DOWNGRADE pattern: write, then read the fresh value with no gap.
    BigDecimal updateAndComputeFactor(BigDecimal newRate) {
        rw.writeLock().lock();                 // exclusive write
        try {
            this.rate = newRate;               // WRITE the new rate
            rw.readLock().lock();              // acquire READ before releasing WRITE
        } finally {
            rw.writeLock().unlock();           // downgrade: now only read held
        }
        try {
            // READ the exact value we just wrote — no other writer could intervene
            return rate.divide(new BigDecimal("36500"), 10, java.math.RoundingMode.HALF_UP);
        } finally {
            rw.readLock().unlock();
        }
    }

    // CORRECT workaround for "need to write after reading": never upgrade in place.
    void demonstrateCorrectUpgradeWorkaround() {
        rw.readLock().lock();
        boolean stale;
        try { stale = rate.compareTo(new BigDecimal("7.00")) < 0; }
        finally { rw.readLock().unlock(); }    // RELEASE read first
        if (stale) {
            rw.writeLock().lock();             // THEN acquire write
            try {
                if (rate.compareTo(new BigDecimal("7.00")) < 0) {  // RE-CHECK, state may have changed
                    rate = new BigDecimal("7.00");
                    log.info("workaround: bumped stale rate to 7.00");
                }
            } finally { rw.writeLock().unlock(); }
        } else {
            log.info("workaround: rate already fresh, no write needed");
        }
    }
}
```

