// ─── File: src/test/java/com/bank/rate/store/RateStoreTest.java ───
package com.bank.rate.store;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.logging.Logger;
import static org.junit.jupiter.api.Assertions.*;

class RateStoreTest {
    @Test
    void downgradeReturnsFactorForFreshRate() {
        RateStore store = new RateStore(new BigDecimal("6.50"), Logger.getLogger("t"));
        BigDecimal factor = store.updateAndComputeFactor(new BigDecimal("7.25"));
        // 7.25 / 36500 computed on the freshly written rate
        assertEquals(new BigDecimal("7.25"), store.readRate());
        assertTrue(factor.signum() > 0);
    }
}
